import { StatusView } from '../../../shared/models/status-tone.model';

/**
 * A customer and/or supplier ("party") as returned by the API.
 *
 * Balance convention everywhere: `balance = debit − credit`.
 *   > 0 → مدين  (the party owes us — typical for customers)
 *   < 0 → دائن  (we owe the party — typical for suppliers)
 */
export interface Party {
  id: string;
  /** Generated by the server: `CU-00012` (customer / both) or `SU-00012` (supplier). */
  code: string;
  kind: PartyKind;
  name: string;
  phone: string;
  phone2: string;
  email: string;
  city: string;
  address: string;
  taxNumber: string;
  commercialRegister: string;
  /** 0 = no limit. */
  creditLimit: number;
  /** Days allowed for credit invoices. */
  paymentTermDays: number;
  priceList: PriceList;
  /** Signed, same convention as `balance`. */
  openingBalance: number;
  notes: string;
  isActive: boolean;
  /** Quick customer registered from the POS screen. */
  isExternal: boolean;
  createdAt: string;

  // ── Computed by the server ──
  balance: number;
  lastMovementAt: string | null;
}

export type PartyPayload = Pick<
  Party,
  | 'kind'
  | 'name'
  | 'phone'
  | 'phone2'
  | 'email'
  | 'city'
  | 'address'
  | 'taxNumber'
  | 'commercialRegister'
  | 'creditLimit'
  | 'paymentTermDays'
  | 'priceList'
  | 'openingBalance'
  | 'notes'
  | 'isActive'
  | 'isExternal'
>;

/** Minimal shape for selects. */
export interface PartyOption {
  id: string;
  code: string;
  name: string;
  kind: PartyKind;
  phone: string;
  balance: number;
  creditLimit: number;
}

export type PartyKind = 'customer' | 'supplier' | 'both';
export type PriceList = 'retail' | 'wholesale';

export const PARTY_KINDS: readonly PartyKind[] = ['customer', 'supplier', 'both'];

export const PARTY_KIND_VIEW: Record<PartyKind, StatusView> = {
  customer: { label: 'عميل', tone: 'info', color: 'var(--bl)' },
  supplier: { label: 'مورد', tone: 'warning', color: 'var(--am)' },
  both: { label: 'عميل ومورد', tone: 'neutral', color: 'var(--pu)' },
};

export const PRICE_LIST_LABEL: Record<PriceList, string> = {
  retail: 'قطاعي',
  wholesale: 'جملة',
};

/** Does `kind` satisfy a document's party role? `both` satisfies either. */
export function partyFits(kind: PartyKind, role: 'customer' | 'supplier'): boolean {
  return kind === 'both' || kind === role;
}

export type BalanceSide = 'debit' | 'credit' | 'zero';

export function balanceSide(balance: number): BalanceSide {
  return balance > 0 ? 'debit' : balance < 0 ? 'credit' : 'zero';
}

export const BALANCE_SIDE_LABEL: Record<BalanceSide, string> = {
  debit: 'مدين',
  credit: 'دائن',
  zero: 'متزن',
};

// ── Statements & balances ──

/** One line of a party's account statement. */
export interface StatementEntry {
  /** Source document / voucher id. */
  sourceId: string;
  sourceType: 'document' | 'voucher' | 'opening';
  /** DocKind or VoucherKind. */
  sourceKind: string;
  number: string;
  date: string;
  description: string;
  debit: number;
  credit: number;
  /** Running balance after this line. */
  balance: number;
}

/** A line of the source document, for the detailed statement. */
export interface StatementLine {
  code: string;
  name: string;
  unit: string;
  qty: number;
  price: number;
  total: number;
}

export interface DetailedStatementEntry extends StatementEntry {
  lines: StatementLine[];
}

export interface PartyStatement<E extends StatementEntry = StatementEntry> {
  party: PartyOption;
  from: string;
  to: string;
  /** Balance before `from`. */
  openingBalance: number;
  totalDebit: number;
  totalCredit: number;
  closingBalance: number;
  entries: E[];
}

/** Row of the balances report (as of a date). */
export interface PartyBalanceRow {
  id: string;
  code: string;
  name: string;
  kind: PartyKind;
  phone: string;
  creditLimit: number;
  totalDebit: number;
  totalCredit: number;
  balance: number;
  /** balance > creditLimit (when a limit is set). */
  overLimit: boolean;
  lastMovementAt: string | null;
}

export interface PartyBalancesSummary {
  count: number;
  /** Sum of positive balances (owed to us). */
  receivable: number;
  /** Sum of |negative balances| (we owe). */
  payable: number;
  net: number;
  overLimitCount: number;
}
